window.RP_SESSION={"id":"S-1da10fa7c4c2","messages":[{"id":"RP-III-0102973","time":"2026-05-24T15:30:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"방 안입니다.\n\n깃털펜 하나를 가볍게 쥐고, 가면도 내버려두고, 양피지 두어 장을 책상에 깔아둔 채.","characters":[]},{"id":"RP-III-0102974","time":"2026-05-24T15:30:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"눈썹 사이를 긁적이며 고심합니다.","characters":[]},{"id":"RP-III-0102975","time":"2026-05-24T15:32:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"빈 양피지를 빤히 쳐다보다가\n\n끄적끄적. 제목으로 단어 몇 글자를 적습니다.","characters":[]},{"id":"RP-III-0102976","time":"2026-05-24T15:32:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"'유언장'","characters":[]},{"id":"RP-III-0102977","time":"2026-05-24T15:33:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"놀라지 마세요.\n죽으려고 생각하는 건 아닙니다.","characters":[]},{"id":"RP-III-0102978","time":"2026-05-24T15:34:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"그냥. 요즘 일련의 사건들을 겪고, 동료의 죽음을 지켜보며 많은 생각이 있었거든요.","characters":[]},{"id":"RP-III-0102979","time":"2026-05-24T15:34:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"이제부터 해야할 일들은 목숨이 너무 쉽게 날아가버릴 지도 모릅니다.\n\n준비되지 않은 죽음이란 건, 남겨진 이들에게 너무 잔혹하니까요.","characters":[]},{"id":"RP-III-0102980","time":"2026-05-24T15:36:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"어쩌면 내 삶을 회고해보면서, 복잡한 감정들을 정리해볼 수 있는 시간이기도 하죠.","characters":[]},{"id":"RP-III-0102981","time":"2026-05-24T15:36:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"끄적끄적... 내용은 비밀입니다.\n\n아직 나는 살아있으니까요.","characters":[]},{"id":"RP-III-0102982","time":"2026-05-24T15:37:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"몇 문장을 쓰고는, 천장을 올려다보았다가.\n\n몇 문장을 쓰고는, 창밖을 내려다보 았다가.","characters":[]},{"id":"RP-III-0102983","time":"2026-05-24T15:37:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"깊은 고심을 하며, 묵묵히 유언장을 써내려 갑니다.","characters":[]},{"id":"RP-III-0102984","time":"2026-05-24T15:56:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"아 참.","characters":[]},{"id":"RP-III-0102985","time":"2026-05-24T15:56:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"먼저 떠난 이의 것은 지금 보여 주어야겠습니다.","characters":[]},{"id":"RP-III-0102986","time":"2026-05-24T15:56:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"...","characters":[]},{"id":"RP-III-0102987","time":"2026-05-24T15:56:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"나는 아직 그대의 부재를 무던하게 눈감아 줄 자신이 없다.","characters":[]},{"id":"RP-III-0102988","time":"2026-05-24T15:57:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"너의 허락도 없이\n\n너에게 너무 많은 마음을\n주어버리고\n뺏겨버리고\n\n빈 우주에서 나는 독백하는 배역을 맡아버렸다.","characters":[]},{"id":"RP-III-0102989","time":"2026-05-24T15:58:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"구태여, 나를 기억할 필요는 없다.\n\n너로 말미암아 나는 나는 사랑을 깨달았고, 별빛되기를 소망하니,\n\n나는 너를 기억해도 너는 나를 기억할 필요가 없다.","characters":[]},{"id":"RP-III-0102990","time":"2026-05-24T16:00:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"사랑하는 법을 모르는 자가\n\n행복할 줄 모르는 자와\n\n손을 잡고\n\n잠시동안 헛된 꿈을 꿨던 것이라 생각하겠다.","characters":[]},{"id":"RP-III-0102991","time":"2026-05-24T16:00:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"그래도, 그래도. 내가 지나치게 사랑했던\n\n당신에겐 행복이 있기를.\n\n당신에게 길이 보이기를.","characters":[]},{"id":"RP-III-0102992","time":"2026-05-24T16:00:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-III-0102993","time":"2026-05-24T16:00:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
